// Kontrollerar att menyvalet och rubriken heter Vreta Sound System (paraplyet för alla band)
// och att den gamla adressen #husbandet fortfarande fungerar. AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const hb = fs.readFileSync('public/husbandet.js', 'utf8');
const mu = fs.readFileSync('public/musik.js', 'utf8');
const krav = {
  menyval: hb.includes("a.textContent = 'Vreta Sound System';") && hb.includes("a.href = '#vreta-sound-system';"),
  rubrik: />Vreta Sound System<\/h1>/.test(hb),
  ingenGammalRubrik: !hb.includes('Husbandets sound') && !hb.includes("a.textContent = 'Husbandet';"),
  allaBandNamns: ['Husbandet', 'Karavanen', 'Ek &amp; Lin', 'Leonid'].every(b => hb.includes(b)),
  gamlaAdressenFungerar: hb.includes("location.hash !== '#husbandet' && location.hash !== '#vreta-sound-system'"),
  inglaGamlaLankar: !/href="#husbandet"/.test(hb + mu),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
